import{_ as e,P as a,d as r,e as s,y as i,q as n,f as o}from"./chunks/framework.D7CAgLCq.js";const N=JSON.parse('{"title":"附录B　编号体系与术语总表","description":"","frontmatter":{"title":"附录B　编号体系与术语总表","xkChars":2327,"xkWords":102,"xkLessons":{"app-b":{"title":"附录B　编号体系与术语总表","lead":"索引让你找到定义与条件，不能替你满足这些条件；同字母、相邻编号和数量都不提供额外证据或权限。","explanation":["原文定位：第4760—4804行，原站定位本分部导语（无独立编号锚点）。当前全文见theory-v2.1来源；历史研究原稿与切片仍按原版下载回查。","短引文：“本表只作导航索引。”附录B回答去哪里找定义与条件，而不以一个前缀代替全文条件。数量是索引条目数量，不是经验成立数量；编号相邻不意味着推理前提或成熟顺序。[T-main]","01｜D0—D3共4项，在第三部分定义结构对象、基本状态词、有效反馈与尺度变换。定义固定语言与界定，不独立证明现实对象符合它。[T-main]","02｜U01—U11共11项，是第三部分的十一个基本结构概念。基本结构概念用于组织对象描述，不是11条已验证普适因果定律。[T-main]","03｜G1—G4共4类经验问题，第四部分每一类都经一次具体检验来回答；引用G编号只是指出问题类别，不能跳过检验资格。[T-main]","04｜法1—法3共3条共同方法约束，在第四部分及附录C，分别管任务与表示、材料身份与支持范围、事实价值与行动资格。这里的“法”不是经验必然规律或现实法律授权。[T-main]","05｜F1—F6共6个条件形式命题，在第四部分及附录C，覆盖任务恢复、动力与允许干预下的闭合、信息约束下的共同可行动作、连续转换的任务保持、近似闭合的误差传播、任务族的最粗充分划分。结论依各自数学条件，不是社会案例因编号相同就自动成立。[T-main]","06｜E1—E5共5项认识论约束，在第四部分。方法约束可要求如何判断，不自行提供现实效应数据。[T-main]","07｜C1—C12共12项，第四部分的十二条结论规则，涵盖结果、机制命题与程序桥接。这个C前缀不同于九轴中的因果层次C；规范桥接要按自身的桥接条件用。[T-main]","08｜A/X/T/O/C/R/I/N/J为第五部分尺度剖面的九个轴，共9个轴，不能压成微观宏观一条线。管辖与授权范围不可由其余轴范围推导；网络拓扑范围N与五项规范前提（N1—N5）也不同。[T-main]","09｜M01—M09共9种第五部分的尺度变换。变换后的保持、损失与新增条件须核，变换的名字不证明迁移有效。[T-main]","10｜CM-*共6种第六部分的条件机制：有效反馈、反馈介导学习、维护与存护—消解、“负荷、容量与恢复”、相位与阈值转换、“变异—差异保留—再生产”。各机制的分支各有条件，不能拿“学习”二字代替载体、时序或作用证据。[T-main]","11｜H1—H6共6项第七部分人类领域条款。具体哪些是经验假设、分类规则或规范边界，应查各条身份，不把它们统一叫作六条实证定律。[T-main]","12｜GC/GS/GE/CV/RS/IS/IM/IB共8个第七部分的类别：生成条件/主体/事件、承接载体、责任主体、失稳来源/机制/行为。原表称“三组不可混装的类别”，但不意味着八个标签可混用；同一现实实体可能有不同角色，各项仍分开取证。[T-main]","13｜HV01—HV11共11项第七部分人类变量，附录A给详表。列出变量不表示某人的变量状态已实测，也不直接产生调整权。[T-main]","14｜S0—S6加X0记作7+1：第八部分七个人类状态原型加一条有序退场路径。7+1不是八阶段，X0不叫S7，编号不排价值等级。[T-main]","15｜IG1—IG7共7闸，是第十三部分唯一主流程；16｜SJ1—SJ8共8项强判断材料；17｜L1—L3共3个诊断档位。流程、强判断件和投入档位是不同维度，不能把它们排成一条连续流程。[T-main]","18｜TOOL-*共6项第十三部分正式工具：来源—证据台账、开放断言记录、命题验证表、前瞻登记、反例与尺度压力测试、AI 输出边界。工具记录可以承载检查，不以表单齐全自证判断正确。[T-main]","19｜N1—N5共5项第十四部分的规范前提，每次规范选择时写明实际采用的是哪几项；20｜O1—O4共4步有限授权的操作程序；21｜PF-1—PF-10共10项保护底板。价值选择、授权程序和保护底板分开；规范N不同于拓扑N，程序O不同于组织尺度O。[T-main]","22｜T0—T4共5个第十五部分干涉层级；23｜APP-*共9个应用模块：关系、家庭、组织与项目、平台、制度与公共治理、公共舆情、空间与通道、应急与高压、超大规模。干涉层级不是经验置信度，应用名也不授予对应领域权限。[T-main]","24｜GOV-01—GOV-24共24条第十六部分治理条款。治理约束与应用模块互相参照，但索引并不替代每条适用条件和行动边界。[T-main]","贯穿记号也要逐项读：S*=<B,X,R,I,T,SP,K>记结构对象界定的七个要素，依次是边界、状态变量、关系或转移约束、接口、时间窗、尺度剖面、同一性判据。这些局部字母不能直接按尺度剖面九轴的同字母解释；S*里的R不是观察分辨率（R），I不是影响范围（I），X不是空间范围（X）。[T-main]","N0记零模型，不是五项规范前提（N1—N5）的零号；K*、F*分别记修复的目标同一性判据与目标功能判据。G-instance、H-instance指经验问题与人类领域条款的一次具体检验，有编号不等于已获得支持。F1—F6是条件形式命题的编号；单独F/F*可能按局部定义为动力更新、功能判据或修复目标，不从同字母推同对象。[T-main]","最后的历史边界是实质提醒：历史增量只检验给定当前表示之外的历史条件增量。载体介导学习、累积、持续与跨期再生产按各机制的条件核，不以历史增量检验获得正向支持为共同前提。查索引时不能因这些词都有时间就一律接历史增量检验。[T-main]","实际查阅顺序是先确定当前句子的命名空间、局部定义、对象与版本，再回到正文的定义与条件，最后查检验材料和可以得出的结论。本附录没有外部经验断言；硬添一个历史个案会把“导航用法”与“理论验证”混淆，因此本题用明确人工命名冲突练习，不冒称历史案例。[T-main]"],"argumentSteps":["识别前缀及局部命名空间，查对应正文部分。","将编号数量与检验支持数量分开。","区分定义、形式、经验、规范、程序和工具身份。","逐次核S*与SP同字母、F/F*、N0/N1—N5的局部定义。","历史增量检验只接当前表示之外的增量，其他跨期条件各自检查。","引用正文条件和检验材料，不用索引替证。"],"distinctions":[{"leftTitle":"S*对象界定","leftText":"七个要素组织候选对象。","rightTitle":"SP尺度剖面","rightText":"九轴范围与分辨率，嵌在对象界定中。"},{"leftTitle":"F1—F6","leftText":"六个条件形式命题的编号。","rightTitle":"F或F*","rightText":"局部动力或功能/目标记号。"},{"leftTitle":"N拓扑轴","leftText":"网络范围。","rightTitle":"N1—N5","rightText":"五项规范前提；N0另为零模型。"},{"leftTitle":"七原型加一路径","leftText":"七种状态原型及“有序退场与良性消亡”。","rightTitle":"八阶段","rightText":"索引未给这种演化序列。"}],"boundaries":["教学反例：把S*中的X按SP的空间轴解释，读取了错误的项。","教学反例：见到“有序退场与良性消亡”便称第八成熟阶段，违背7+1的类型区分。","原文边界：不能因出现学习或跨期字样就一律要求历史增量检验的正向支持。","原文边界：导航表不替代正文的定义、条件及使用限制。"],"questions":["表中数量能当已验证理论数吗？","F*一定是F1—F6的某一项吗？","历史增量检验是所有跨期学习的前提吗？","怎样避免同字母误读？"],"diagramPath":"/reading-assets/APP-B/figures/index-lookup.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"app-b","start_line":4404,"end_line":4441,"startLine":4404,"endLine":4441}],"outputId":"app-b","sourceHash":"2128af7cfa4c63b58207521a375aa34c2aea230d47e1c04a5afec3334e290d28","teachingExamples":[{"title":"教学构造：同字母仍需局部定义","text":"人工记录写S*.R=角色间关系，SP.R=按周汇总分辨率。这不是同一R的矛盾赋值，而是对象界定与尺度剖面的不同项。若把前者填进后者，会同时丢掉关系和压缩损失。","assumptions":"两份记录和赋值均虚构，只演示命名空间。","boundary":"没有现实对象认定或因果结论。"},{"title":"教学构造：7+1的算术不能变阶段论","text":"索引包含7种状态原型和1条“有序退场与良性消亡”路径，条目数可以算8，但类型仍是7+1。数量相加不产生第八状态，也不产生必须走完7个原型才能退出的条件。","assumptions":"只作集合计数解释，名称来自用户原文。","boundary":"不外推组织演化规律或退场授权。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学反例：把S*中的X按SP的空间轴解释，读取了错误的项。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：见到“有序退场与良性消亡”便称第八成熟阶段，违背7+1的类型区分。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：不能因出现学习或跨期字样就一律要求历史增量检验的正向支持。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：导航表不替代正文的定义、条件及使用限制。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"表中数量能当已验证理论数吗？","answer":"不能，它们是索引条目数量，证据状态另查。","basis":"导航边界。"},{"question":"F*一定是F1—F6的某一项吗？","answer":"不一定，局部定义决定，不能仅按字母对应。","basis":"贯穿记号。"},{"question":"历史增量检验是所有跨期学习的前提吗？","answer":"不是，它限定当前表示之外的历史增量，其他路线按各自的条件。","basis":"附录末段。"},{"question":"怎样避免同字母误读？","answer":"先标对象界定/尺度/规范/形式命题等命名空间，再读局部定义。","basis":"同名不等于同物。"}],"figures":[{"path":"/reading-assets/APP-B/figures/index-lookup.png","alt":"前缀查正文的定义与条件，再核检验证据与上限，数量不等于支持。","caption":"据附录B导航性质。"},{"path":"/reading-assets/APP-B/figures/index-names.png","alt":"S*与SP、F1—F6与F/F*、N0与N规范/网络、S与X0分开。","caption":"据附录B末段及编号表。"}],"diagramBrief":"两图展示索引使用路径和主要命名冲突；完整24行及贯穿记号均在正文逐项解释。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节为用户理论内部编号与记号导航，不提出外部历史事实或经验效应；使用明示教学命名冲突练习，不为凑案例虚构历史。"},"openQuestions":["本索引不能代替各正文的定义与条件或现实个案的来源核查。"],"taskId":"APP-B","sources":[{"id":"T-main","title":"历史研究稿：Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§app-b，第4318—4355行","claim_support":["全部24行索引、贯穿记号与G3边界。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。","此条保留原研究的版本、定位与核读范围；不是 v2 外部来源复核记录。当前理论请见 theory-v2.1。"],"access_status":"read"},{"id":"theory-v2.1","title":"Xikari-条件结构与转化论，v2.1，2026年11月","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2.1 / 2026-11-19","locator":"附录B　编号体系与术语总表；SHA-256 2128af7cfa4c63b58207521a375aa34c2aea230d47e1c04a5afec3334e290d28","claim_support":["当前原文章节及本文对 v2.1 的概念说明；不代替外部经验材料。"],"limits":["旧研究附件保持原稿身份，原有外部核读范围没有因本次换版扩大。"],"access_status":"read"}],"lecturePath":"/reading-assets/APP-B/lecture.md","sourcesPath":"/reading-assets/APP-B/sources.json","sourceSlicePath":"/reading-assets/APP-B/source/APP-B.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/APP-B/diagrams.md","editionNote":"本页原文、章节定位和讲解用词都对应 v2.1；历史研究附件和原有外部核读记录保持各自版本与范围。"}}},"headers":[],"relativePath":"theory/appendix-b.md","filePath":"theory/appendix-b.md"}'),c={name:"theory/appendix-b.md"};function p(l,t,T,S,m,u){const d=a("SectionLesson");return r(),s("div",null,[t[0]||(t[0]=i('<div class="theory-source"><p><a id="part_18"></a></p><h1 id="part-title-18" tabindex="-1"><span class="xk-part">附录B<span class="xk-part__gap">　</span></span>编号体系与术语总表 <a class="header-anchor" href="#part-title-18" aria-label="Permalink to &quot;附录B　编号体系与术语总表 {#part-title-18}&quot;">​</a></h1><p>全书使用下列编号体系。正文叙述一律用中文名称，编号只标在各项定义所在小节的标题末尾。本表只作导航索引，各体系的定义、条件与使用边界以正文相应部分为准。</p><div class="xk-table"><table><thead><tr><th>编号</th><th>名称</th><th>数量</th><th>定义所在</th></tr></thead><tbody><tr><td>D、G、E、H、N、O、F</td><td>命题的七种角色：定义；经验问题；认识论约束；人类领域条款；规范承诺；操作程序；条件形式命题</td><td>7</td><td>第二部分（§2.2）</td></tr><tr><td>EVIDENCE、CAUSAL、ANALOGY、SOURCE</td><td>四项方法条件：证据的条件；因果主张的条件；类比的条件；来源的条件</td><td>4</td><td>第二部分（§2.4—§2.7）</td></tr><tr><td>D0—D3</td><td>定义层：结构对象；基本状态词；有效反馈；尺度变换</td><td>4</td><td>第三部分（§3.1—§3.4）</td></tr><tr><td>U01—U11</td><td>十一个基本结构概念：候选对象；边界与接口；状态与可观察量；组件、载体与基质；关系与约束；流、通道与传导；反馈与状态更新；条件与环境；负荷、容量与恢复余量；留痕、记忆与路径；相位、转移与解体</td><td>11</td><td>第三部分（§3.5）</td></tr><tr><td>G1—G4</td><td>四类经验问题：分组增益（候选分组的条件增益）；通道效应（指定通道效应）；历史增量（当前表示之外的历史条件增量）；尺度闭合（表示闭合与对象或干预转换）。每一类都经一次具体检验来回答，分别称分组增益检验、通道效应检验、历史增量检验、尺度闭合检验</td><td>4</td><td>第四部分（§4.3—§4.6）</td></tr><tr><td>G1a—G4b</td><td>四类经验问题各自的两种子型：分组增益分预测增益型、干预增益型；通道效应分受控识别型、自然变异型；历史增量分预测性路径依赖、因果性路径依赖；尺度闭合分闭合失败型、对象或干预转换型</td><td>8</td><td>第四部分</td></tr><tr><td>法1—法3</td><td>三条共同方法约束：任务与表示须共同声明；材料身份与支持范围须可追溯；事实、价值与行动资格分别成立</td><td>3</td><td>第四部分（§4.17）及附录C</td></tr><tr><td>F1—F6</td><td>条件形式命题：任务恢复；动力与允许干预下的闭合；信息约束下的共同可行动作；连续转换的任务保持；近似闭合的误差传播；任务族的最粗充分划分</td><td>6</td><td>第四部分（§4.18—§4.19）及附录C</td></tr><tr><td>E1—E5</td><td>五条认识论约束：对象声明约束；观察位置与模型限制；条件性观测参与；竞争解释与残差保留；跨尺度迁移检验</td><td>5</td><td>第四部分（§4.8）</td></tr><tr><td>C1—C12</td><td>十二条结论规则，涵盖结果、机制命题与程序桥接：分组增益及其边界扰动稳健性；承载与通道约束；有效反馈与反馈介导学习；历史作用、路径差异与修复窗口；负荷、容量与恢复；尺度闭合与对象转换；局部改善与跨边界溢出；变异—差异保留—再生产；观测通道与反身响应；人类承接与跨期再生产；制度写回；规范桥接</td><td>12</td><td>第四部分（§4.10—§4.14）</td></tr><tr><td>A、X、T、O、C、R、I、N、J</td><td>尺度剖面的九个轴：聚合层次；空间范围；时间跨度；组织层级；因果层次；观察分辨率；影响范围；网络拓扑范围；管辖与授权范围</td><td>9</td><td>第五部分（§5.2）</td></tr><tr><td>M01—M09</td><td>九种尺度变换：聚合；嵌套；网络传播；时间累积；制度化；涌现；委托或代表；压缩或抽象；横向迁移</td><td>9</td><td>第五部分（§5.5）</td></tr><tr><td>CM-*</td><td>六种条件机制：有效反馈（FEEDBACK）；反馈介导学习（LEARNING）；维护与存护—消解（MAINTENANCE）；负荷、容量与恢复（LOAD）；相位与阈值转换（PHASE）；变异—差异保留—再生产（SELECTION）</td><td>6</td><td>第六部分（§6.2—§6.8）</td></tr><tr><td>H1—H6</td><td>六项人类领域条款：意义与协调；行动承接与责任分型；制度写回；权力、中介与反身性；历史留痕载体；开放性承担</td><td>6</td><td>第七部分（§7.1）</td></tr><tr><td>GC、GS、GE、CV、RS、IS、IM、IB</td><td>三组不可混装的类别：生成条件、生成主体、生成事件，承接载体，责任主体，失稳来源、失稳机制、失稳行为</td><td>8</td><td>第七部分（§7.2）</td></tr><tr><td>HV01—HV11</td><td>十一项人类变量：结构域；边界与接口；指向锚点；生成节点；行动承接层；动力—承接链；反馈写回；条件势场；结构负荷；演化相位；开放性承担行动（详表见附录A）</td><td>11</td><td>第七部分（§7.3）</td></tr><tr><td>S0—S6、X0</td><td>七种人类状态原型：锚点凝聚；生成核心奠基；首次扩展与承接分化；连通约束下的发展；结构重构窗口；高效协调与弹性扩展；自适应动态平衡。另有有序退场与良性消亡这条路径</td><td>7+1</td><td>第八部分（§8.3、§8.5）</td></tr><tr><td>IT1—IT4</td><td>四次转换：结构变量到可观察信号；信号到证据强度；证据强度到判断等级；判断等级到行动要求与上限</td><td>4</td><td>第十三部分（§13.1）</td></tr><tr><td>IG1—IG7</td><td>七闸，即唯一的主流程：有效对象闸；证据追踪闸；受影响位置闸；权力与反报复闸；中介与反身性闸；强判断程序闸；行动上限闸</td><td>7</td><td>第十三部分（§13.3）</td></tr><tr><td>FG1—FG5、DS01—DS13</td><td>五闸：对象闸；证据闸；尺度闸；责任闸；观测闸。另有十三步，各步名称见正文</td><td>5、13</td><td>第十三部分（§13.4）</td></tr><tr><td>SJ1—SJ8</td><td>强判断八件套：反向条件；修复窗口；证据要求；申诉入口；反报复保护；证据补充权；外部复核触发；恢复原状与写回</td><td>8</td><td>第十三部分（§13.5）</td></tr><tr><td>L1—L3</td><td>三个诊断档位：轻量描述；标准判断；强判断候选</td><td>3</td><td>第十三部分</td></tr><tr><td>TOOL-*</td><td>六项正式工具：来源—证据台账（EVIDENCE-LEDGER）；开放断言记录（OPEN-ASSERTION）；命题验证表（CLAIM-VALIDATION）；前瞻登记（FORECAST-REGISTRY）；反例与尺度压力测试（STRESS-TEST）；AI 输出边界（AI-BOUNDARY）</td><td>6</td><td>第十三部分（§13.7）</td></tr><tr><td>DF1—DF9</td><td>九闸：事实定格；联合对象；双通道与时钟；机制传播；路径分叉；前瞻登记；规范选择；授权与执行；结果回写</td><td>9</td><td>第十三部分（§13.10）</td></tr><tr><td>SEL-SYS、SEL-AGT、SEL-GOV</td><td>三种类型：系统筛选；主体决策；集体治理</td><td>3</td><td>第十四部分（§14.2）</td></tr><tr><td>N1—N5</td><td>五项规范前提，每次规范选择时写明实际采用的是哪几项：解释不授权处置；保护不得降级；高影响判断可纠错；不征用爱与承担；存续与筛选不等于正当</td><td>5</td><td>第十四部分（§14.3）</td></tr><tr><td>NSP-LEAST-HARM、NSP-PROPORTIONALITY</td><td>最小伤害原则；比例原则</td><td>2</td><td>第十四部分（§14.4）</td></tr><tr><td>O1—O4</td><td>有限授权的四步操作程序：固定事实与证据；写明规范前提与冲突；审查授权并比较方案；有限执行与纠错</td><td>4</td><td>第十四部分（§14.6）</td></tr><tr><td>PF-1—PF-10</td><td>保护底板十项：列明受影响位置与低权力位置；低暴露的提交渠道；拒绝与停止真实有效；有效申诉；反报复；补证与记录纠正；外部独立复核；撤回、恢复原状与修复的实际能力；真实退出与替代承接；行动上限与到期</td><td>10</td><td>第十四部分（§14.8）</td></tr><tr><td>T0—T4</td><td>五个干涉层级：安全与信任载体；可逆最小秩序；承接—回流链修复；深时间维护与高阶更新；退出、转移与演化记忆保存</td><td>5</td><td>第十五部分（§15.2）</td></tr><tr><td>APP-*</td><td>九个应用模块：关系（REL）；家庭（FAM）；组织与项目（ORG）；平台（PLT）；制度与公共治理（INS）；公共舆情（OPI）；空间与通道（SPC）；应急与高压（EMG）；超大规模（ULS）</td><td>9</td><td>第十五部分（§15.3）</td></tr><tr><td>GOV-01—GOV-24</td><td>二十四条治理条款：框架自诊与对象分离；共识程序与版本权限；经验断言的纠错与四类经验问题的取舍；案例、反例、断言与前瞻追踪；前概念闸与概念有效性上限；缺席信号、保护性不透明与压制性不透明；自适应动态平衡原型的运作边界与观测递归收束；恶意合规与选择性证据核查；AI 边界与过程性产物非证明性；弱信号六件套保护；无制度基础设施的中间路径；无法退出主体保护；复杂创伤与无健康基准；开放承担、规范前提与隐喻漂移分流；知识谱系与来源透明；使用门槛债与可及性审查；工具化、商业化、武器化与分支风险；开放断言的权力捕获退场；版本写回与反馈闭环；外部评审材料包与公开发布前的检查；框架良性消亡与替代衔接；多圈层复杂度与前瞻治理；人格、隐私与自动化越权治理；模型退化、退役与替代</td><td>24</td><td>第十六部分（§16.1—§16.24）</td></tr></tbody></table></div><p>另有若干贯穿全书的记号：S*=&lt;B,X,R,I,T,SP,K&gt; 记结构对象界定的七个要素，依次是边界、状态变量、关系或转移约束、接口、时间窗、尺度剖面和同一性判据；N0 记零模型；K*、F* 分别记修复的目标同一性判据与目标功能判据；G-instance、H-instance 指经验问题与人类领域条款的一次具体检验。均以正文首次定义处为准。</p><p>F1—F6 是条件形式命题的编号；单独的 F 及 F* 按所在处的局部定义，可以分别表示动力更新、功能判据或修复目标，不凭字母相同推定为同一对象。历史增量（G3）只检验给定当前表示之外的历史条件增量；载体介导的学习、累积、持续效应与跨期再生产，按各自机制的条件检验，不以历史增量检验获得正向支持作为共同前提。</p></div>',1)),n(d,{section:"app-b"}),t[1]||(t[1]=o("div",{class:"theory-source"},null,-1))])}const A=e(c,[["render",p]]);export{N as __pageData,A as default};
